    "clinicalCase": "Um adolescente com 11 anos de idade é atendido no pronto-socorro com história de dor e inchaço em joelho esquerdo há 5 dias. Ele conta que, há 2 dias, iniciou com febre, dificuldade para deambular e aumento da dor e do inchaço na região. A mãe relata recusa alimentar e palidez cutânea há 1 dia. O adolescente apresenta antecedente de trauma local durante partida de futebol há 1 semana e refere o uso de anti-inflamatório não esteroidal desde então, sem melhora do quadro. Ao exame físico, apresenta-se em regular estado geral, com palidez cutânea, febril (temperatura axilar = 38,2 oC), eupneico, anictérico, acianótico, com tempo de enchimento capilar de 3 segundos e pressão arterial normal para a idade. Apresenta, ainda, edema, rubor, calor e dor no joelho esquerdo, com bloqueio à tentativa de mobilização. O resultado do hemograma mostra leucocitose com desvio à esquerda. Também foram observados proteína C reativa e VHS elevados. Nesse caso, quais são o agente etiológico mais provável e a antibioticoterapia endovenosa indicada?",
