    "clinicalCase": "Um paciente com 70 anos de idade, com sequela de acidente vascular encefálico, acamado, apresenta quadro de distensão abdominal, dor tipo cólica intensa e parada de eliminação de gases e fezes há cerca de 24 horas. Nega vômitos ou febre. A acompanhante informou que o paciente já apresentava constipação crônica, sendo muitas vezes necessário clister glicerinado para retirada de fecaloma. Entretanto, desta vez, relata que realizou o clister, sem saída de fezes e com piora do quadro abdominal. O exame do abdome estava prejudicado pela pouca interação do paciente, mas ele manifestava dor à palpação difusa. O toque retal mostrou ampola retal vazia. Realizaram-se as radiografias de rotina para abdome agudo, o que evidenciou, além de imagem de fecaloma, intensa dilatação de todo o cólon (mais dilatado no ceco – 11 cm de diâmetro), ausência de gás no reto e ausência de dilatação de intestino delgado. A conduta médica indicada para esse paciente é",
