    "clinicalCase": "Uma adolescente com 13 anos de idade é atendida no pronto-socorro por apresentar “perda de força nas pernas”. Segundo a mãe, a adolescente está doente há mais de um mês; na primeira semana da doença, teve febre alta que durou 5 dias, dor de garganta, dores no corpo e cansaço extremo. Ela informa, ainda, que a filha foi diagnosticada com amigdalite, recebeu amoxicilina por 7 dias e que, durante esse tratamento, apresentou manchas vermelhas levemente pruriginosas pelo corpo. A mãe relata também que, após desaparecimento da febre, a adolescente persistiu com desânimo por cerca de 3 semanas e, quando parecia estar se recuperando, começou a queixar-se de dor e formigamento nos pés e pernas, com dificuldade progressiva para caminhar e que, hoje, não havia conseguido levantar-se da cama. Ao exame físico, a paciente apresenta paraparesia simétrica e diminuição de força muscular em membros superiores, reflexos osteotendinosos diminuídos em membros superiores e abolidos nos membros inferiores. Em relação a esse quadro clínico, quais são as principais hipóteses diagnósticas?",
