    "clinicalCase": "Uma mulher com 44 anos de idade é encaminhada para avaliação de nódulos mamários múltiplos, inicialmente atribuídos a possível doença fibrocística benigna da mama. A razão do encaminhamento ao especialista é a preocupação da paciente com o fato de uma tia paterna, com 68 anos de idade, ter sido recentemente diagnosticada com câncer de mama (adenocarcinoma ductal infiltrante). A paciente é multípara (G4P5), tendo sua primeira gestação ocorrido aos 36 anos de idade. Amamentou todos os filhos por pelo menos 1 ano. Sua menarca foi tardia, ocorrendo aos 16 anos de idade. Relata que seus ciclos menstruais são indolores e regulares, a cada 28 dias (3 dias de duração), com fluxo em volume normal. Mantém relações sexuais regulares, com parceiro único e sem uso de preservativo. Ela nega possuir comorbidades e alergias. No exame das mamas, são palpados múltiplos nódulos de consistência fibroelástica bilaterais, no meio dos quais é palpado um nódulo sólido, indolor e pouco móvel, de 2,0 cm de diâmetro, localizado no quadrante superior externo da mama esquerda; não há alterações cutâneas locais nem linfonodomegalias satélites, axilares, supraclaviculares ou cervicais. No exame físico geral, a paciente se encontra em bom estado, corada, com IMC = 23,5 kg/m2. Além do nódulo sólido palpável, qual é o outro fator de risco para câncer de mama que a paciente apresenta?",
