    "clinicalCase": "Uma paciente com 34 anos de idade, vítima de acidente automobilístico, apresentando trauma abdominal contuso sem evidências de lesões em outros segmentos corpóreos, foi levada ao pronto-socorro do Centro de Referência de Trauma de nível terciário para atendimento. No atendimento em cena pela equipe de suporte avançado do Serviço de Atendimento Móvel de Urgência (SAMU), foram infundidos 500 mL de ringer lactato. No exame físico da paciente, obteve-se os seguintes resultados: FC = 110 bpm, enchimento capilar = 6 segundos, PA = 100 x 70 mmHg, Glasgow = 15. Houve normalização dos sinais vitais após a infusão de mais 500 mL de solução cristaloide no atendimento inicial. Os exames laboratoriais mostraram os seguintes resultados: Hb = 10,5 g/dL (valor de referência: 12 a 14 g/dL), Ht = 31 % (valor de referência: 35 a 45 %), lactato = 2,8 mmol/L (valor de referência: < 2,0 mmol/L), INR = 1,0 (valor de referência: 0,8 a 1,2), fibrinogênio = 200 mg/dL (valor de referência: 185,0 a 400,0 mg/dL), plaquetas = 120 000/mm3 (valor de referência: 100 000 a 424 000/mm3). A tomografia computadorizada de abdome com contraste endovenoso é mostrada na imagem a seguir. Não foram evidenciadas outras lesões no abdome. Tomografia computadorizada de abdome Com base na história clínica, nos dados do exame físico e na imagem da tomografia, a conduta médica adequada é indicar",
