    "clinicalCase": "Uma mulher com 64 anos de idade é encaminhada para investigação diagnóstica de quadro de tosse seca e dispneia ao realizar esforços. A paciente é portadora, há 3 décadas, de hipertensão arterial sistêmica, sendo tabagista e etilista social. Seu exame físico revela IMC = 33 kg/m2, eupneica em repouso, mas com acrocianose (+/4+) e murmúrio vesicular reduzido difusamente, sendo auscultados sibilos esparsos em todo tórax. O ritmo cardíaco é regular, em 2 tempos, com 2.a bulha hiperfonética em foco pulmonar. Há turgência de veia jugular quando a cabeceira da maca é elevada a 45 graus, além de edema de membros inferiores (2+/4+). A paciente traz à consulta uma espirometria realizada recentemente que evidencia um volume expiratório forçado no 1.o segundo (VEF1) reduzido (68 % do previsto com base em sua idade e altura), sendo a relação entre esse parâmetro e a capacidade vital forçada (VEF1/CVF) inferior a 70 %; não há elevação de 20 % ou aumento superior a 200 mL em nenhum desses dois parâmetros espirométricos após a administração de broncodilatador. Com base no caso clínico e no resultado da espirometria, qual é o diagnóstico da paciente?",
