    "clinicalCase": "Uma mulher com 25 anos de idade vai ao ambulatório de ginecologia com queixa de dor pélvica há 24 horas. Possui ciclos regulares de 28 dias (3 a 4 dias) e a sua última menstruação ocorreu há 3 semanas. No exame clínico, observou-se PA = 110 x 70 mmHg e pulso = 84 bpm. Notou-se dor à palpação profunda em fossa ilíaca esquerda e em região hipogástrica, Blumberg negativo. Sem outras anormalidades durante o exame físico. Foi realizada ultrassonografia transvaginal que revelou estrutura cística no ovário esquerdo, medindo 7,0 x 6,5 cm, sem fluxo ao estudo Doppler, conforme indica imagem a seguir. Ultrassonografia transvaginal Considerando o caso clínico apresentado e a hipótese diagnóstica mais provável, qual deve ser a conduta médica?",
