    "clinicalCase": "Uma mãe leva seu filho de 5 anos de idade para atendimento, na Unidade Básica de Saúde, relatando febre persistente há 24 horas, diminuição do apetite, náuseas e vômitos. A criança amanheceu febril, com cefaleia e sede. A mãe relata que a criança frequentou uma festa de aniversário há cerca de 5 dias. Ela tem vacinação em dia. No exame físico, os resultados de sua avaliação foram os seguintes: pouco reativa; FC = 130 bpm; FR= 30 irpm; temperatura axilar = 38,8 °C; Sat. O2 = 96 %; mucosas desidratadas 3+/4+; petéquias puntiformes em membros inferiores, tórax e abdome. Ele possui dor à flexão da coluna cervical. Nesse caso, qual é a conduta médica adequada?",
