    "clinicalCase": "Um lactente com 2 meses de idade é atendido na emergência, acompanhado pela mãe, que relata vômitos pós-prandiais desde os 15 dias de vida, com piora progressiva em frequência e intensidade. Ela conta que, após tais episódios eméticos, o lactente chora e parece ter fome. Informa, ainda, que seu filho nasceu a termo, com peso de 3 000 g e 49 cm de comprimento e que os testes de triagem neonatal foram normais. Ela nega a ocorrência de doenças gestacionais e perinatais. Ao exame físico, o lactente apresenta-se emagrecido (peso = 3 200 g), ativo, acianótico, anictérico, desidratado (1+/4+) e corado, com abdome distendido, especialmente na região epigástrica, notando-se ausência de hepatoesplenomegalia e presença de ondas de Kussmaul observadas após a alimentação. Os exames laboratoriais iniciais revelam pH = 7,5 (valor de referência: 7,35 a 7,45); HCO3 = 27 mEq/L (valor de referência: 23 a 28 mEq/L); Na = 135 mmol/L (valor de referência: 136 a 145 mmol/L); Cl = 95 mmol/L (valor de referência: 98 a 106 mmol/L) e K = 4,5 mmol/L (valor de referência: 3,5 a 5,5 mmol/L). Nesse caso, a conduta médica adequada é",
