    "clinicalCase": "Em uma reunião da Unidade de Saúde da Família, com a presença dos membros das cinco equipes de Saúde da Família, incluindo os Agentes Comunitários de Saúde (ACS), decidiu-se que, em razão do aumento do número de usuários sem cadastro que passaram a procurar a unidade para atendimento, seria iniciado o processo de atualização da territorialização, que inclui várias etapas e principia pela fase preparatória. Considerando-se essa situação, que conjunto de ações e/ou atividades está incluído na etapa preparatória do processo de territorialização?",
