    "clinicalCase": "Uma paciente com 35 anos de idade procura atendimento hospitalar devido a episódio único de sangramento anal vermelho vivo, indolor, em pequena quantidade durante evacuação. Nega qualquer história prévia de traumatismo local. Em seu exame físico, constatou-se que a paciente está em bom estado geral, normocorada, PA = 120 x 60 mmHg, FC = 76 bpm e com pulso radial amplo, regular. Abdome plano e depressível, indolor à palpação, sem massas palpáveis e sem sinais de irritação peritoneal. A anuscopia não demonstrou doença hemorroidária externa e/ou fissuras anais e/ou fístulas perianais. O toque retal não identificou lesões palpáveis, até cerca de ± 6 cm da margem anal, porém, evidenciou discreta quantidade de sangue em dedo-de-luva. O médico assistente solicitou hemograma, cujo resultado foi normal. A paciente foi liberada com encaminhamento ambulatorial e com solicitação de exame de colonoscopia. O resultado da colonoscopia mostrou alguns pólipos colônicos, não pediculados, e lesão de borda elevada com ulceração central, séssil, ± 1,5 cm de diâmetro, em cólon sigmoide, distando ± 35 cm da margem anal – a qual foi biopsiada. Nesse caso clínico, a hipótese diagnóstica mais provável para essa paciente é de",
